+                        } else if (c == 'a' || c == 'A') {
+                            async_scroll = !async_scroll;
+                        } else if (c == 'b' || c == 'B') {
+                            bold_chars = !bold_chars;
+                        } else if (c == 'n' || c == 'N') {
+                            no_bold = 1;
+                            bold_chars = 0;
+                        } else if (c >= '0' && c <= '9') {
+                            delay = c - '0';
+                        } else if (c == '!' || c == '@' || c == '#' || c == '$' || 
+                                   c == '%' || c == '^' || c == '&' || c == ')') {
+                            if (c == '!') color = 'r';
+                            else if (c == '@') color = 'g';
+                            else if (c == '#') color = 'y';
+                            else if (c == '$') color = 'b';
+                            else if (c == '%') color = 'm';
+                            else if (c == '^') color = 'c';
+                            else if (c == '&') color = 'w';
+                            else if (c == ')') color = 'k';
+                        }
+                    }
+                    key_pressed = 1;
+                }
+            }
+        }
+        
+        // Check for lock mode close
+        if (lock_mode && tty_set) {
+            // Check if terminal is closed
+            if (tcgetattr(tty_fd, NULL) == -1) {
+                break;
+            }
+        }
+        
+        // Check for screensaver mode key
+        if (screensaver_mode && key_pressed) {
+            break;
+        }
+    }
+    
+    // Restore terminal mode
+    restore_term_mode();
+    
+    // Close tty if opened
+    if (tty_fd != -1) {
+        close(tty_fd);
+    }
+    
+    return 0;
+}
