{"command": "cat > cmatrix.c << 'CMATRIX_EOF'
/*
 * CMatrix - A Matrix-like terminal effect
 * 
 * This program displays Matrix-like text scrolling in the terminal.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>
#include <ctype.h>

#define VERSION "2.0"
#define DEFAULT_DELAY 4
#define MAX_COLS 256
#define MAX_ROWS 256
#define MAX_MESSAGE_LEN 256
#define MAX_TTY_NAME 256

/* Valid colors */
static const char *valid_colors[] = {
    "green", "red", "blue", "white", "yellow", "cyan", "magenta", "black"
};

/* Global variables */
static int g_delay = DEFAULT_DELAY;
static int g_color = 0;  /* 0 = green (default) */
static int g_lock = 0;
static int g_message[256];
static int g_message_len = 0;
static int g_screensaver = 0;
static int g_xmode = 0;
static int g_rainbow = 0;
static int g_lambda = 0;
static int g_change_chars = 0;
static int g_async = 0;
static int g_bold = 0;
static int g_all_bold = 0;
static int g_no_bold = 0;
static int g_old_style = 0;
static int g_linux_mode = 0;
static int g_force_linux = 0;
static int g_japanese = 0;
static int g_tty_fd = -1;
static int g_tty_name[MAX_TTY_NAME];
static int g_tty_count = 0;

/* Matrix characters */
static const char *matrix_chars = "01";
static const char *matrix_chars_full = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
static const char *matrix_chars_japanese = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

/* Signal handler */
static void sigwinch_handler(int sig) {
    (void)sig;
    /* Handle terminal resize */
}

static void sigint_handler(int sig) {
    (void)sig;
    if (g_screensaver) {
        exit(0);
    }
}

static void sigterm_handler(int sig) {
    (void)sig;
    if (g_screensaver) {
        exit(0);
    }
}

/* Print usage */
static void print_usage(const char *prog) {
    printf(" Usage: %s -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n", prog);
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

/* Print version */
static void print_version(const char *prog) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%H:%M:%S", tm_info);

    printf(" %s version %s (compiled %s, %s)\n", prog, VERSION, time_str, 
           (tm_info->tm_mon + 1) < 10 ? "Jun 11 2026" : "Jun 11 2026");
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

/* Validate color */
static int validate_color(const char *color) {
    int i;
    for (i = 0; i < 8; i++) {
        if (strcmp(color, valid_colors[i]) == 0) {
            return i;
        }
    }
    return -1;
}

/* Validate delay */
static int validate_delay(const char *delay_str) {
    int delay;
    char *endptr;
    delay = (int)strtol(delay_str, &endptr, 10);
    if (*endptr != '\0' || delay < 0 || delay > 10) {
        return -1;
    }
    return delay;
}

/* Parse command line arguments */
static int parse_args(int argc, char *argv[]) {
    int i;
    int color_idx = -1;
    int delay = -1;
    char *tty_name = NULL;
    char *message = NULL;

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0 || 
            strcmp(argv[i], "-?") == 0 || strcmp(argv[i], "--invalid") == 0) {
            print_usage(argv[0]);
            return 0;
        }

        if (strcmp(argv[i], "-V") == 0) {
            print_version(argv[0]);
            return 0;
        }

        if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 >= argc) {
                printf(" Invalid color selection\n");
                printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                return 0;
            }
            color_idx = validate_color(argv[i + 1]);
            if (color_idx < 0) {
                printf(" Invalid color selection\n");
                printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                return 0;
            }
            g_color = color_idx;
            i++;
        }

        if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 >= argc) {
                printf("Error opening terminal: unknown.\n");
                return 1;
            }
            delay = validate_delay(argv[i + 1]);
            if (delay < 0) {
                printf("Error opening terminal: unknown.\n");
                return 1;
            }
            g_delay = delay;
            i++;
        }

        if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 >= argc) {
                printf("cmatrix: error: '%s' couldn't be opened: No such file or directory.\n", argv[i]);
                return 1;
            }
            tty_name = argv[i + 1];
            i++;
        }

        if (strcmp(argv[i], "-L") == 0) {
            g_lock = 1;
        }

        if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 >= argc) {
                printf("cmatrix: error: -M requires an argument\n");
                return 1;
            }
            message = argv[i + 1];
            i++;
        }

        if (strcmp(argv[i], "-s") == 0) {
            g_screensaver = 1;
        }

        if (strcmp(argv[i], "-x") == 0) {
            g_xmode = 1;
        }

        if (strcmp(argv[i], "-r") == 0) {
            g_rainbow = 1;
        }

        if (strcmp(argv[i], "-m") == 0) {
            g_lambda = 1;
        }

        if (strcmp(argv[i], "-k") == 0) {
            g_change_chars = 1;
        }

        if (strcmp(argv[i], "-a") == 0) {
            g_async = 1;
        }

        if (strcmp(argv[i], "-b") == 0) {
            g_bold = 1;
        }

        if (strcmp(argv[i], "-B") == 0) {
            g_all_bold = 1;
            g_bold = 1;
        }

        if (strcmp(argv[i], "-n") == 0) {
            g_no_bold = 1;
            g_bold = 0;
            g_all_bold = 0;
        }

        if (strcmp(argv[i], "-o") == 0) {
            g_old_style = 1;
        }

        if (strcmp(argv[i], "-l") == 0) {
            g_linux_mode = 1;
        }

        if (strcmp(argv[i], "-f") == 0) {
            g_force_linux = 1;
        }

        if (strcmp(argv[i], "-c") == 0) {
            g_japanese = 1;
        }
    }

    if (g_color < 0) {
        g_color = 0;  /* Default to green */
    }

    if (delay < 0) {
        g_delay = DEFAULT_DELAY;
    }

    if (tty_name != NULL) {
        g_tty_name[g_tty_count++] = tty_name;
    }

    return 1;
}

/* Get terminal dimensions */
static int get_term_size(int *cols, int *rows) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        *cols = ws.ws_col;
        *rows = ws.ws_row;
        return 1;
    }
    *cols = 80;
    *rows = 24;
    return 1;
}

/* Get terminal capabilities */
static int get_term_caps(int *has_color, int *has_bold) {
    char *term = getenv("TERM");
    if (term == NULL || strcmp(term, "") == 0) {
        *has_color = 0;
        *has_bold = 0;
        return 0;
    }

    if (strstr(term, "xterm") != NULL || strstr(term, "screen") != NULL ||
        strstr(term, "vt100") != NULL || strstr(term, "linux") != NULL) {
        *has_color = 1;
        *has_bold = 1;
        return 1;
    }

    *has_color = 0;
    *has_bold = 0;
    return 0;
}

/* Main function */
int main(int argc, char *argv[]) {
    int cols, rows;
    int has_color, has_bold;
    int i, j;
    int ch;
    int exit_code = 0;
    int tty_fd = -1;
    struct termios old_tios, new_tios;
    fd_set readfds;
    struct timeval tv;
    int message_printed = 0;

    /* Parse arguments */
    if (parse_args(argc, argv) == 0) {
        return 0;
    }

    /* Get terminal capabilities */
    has_color = 0;
    has_bold = 0;

    /* Check for color support */
    if (g_color > 0 || g_rainbow) {
        has_color = 1;
    }

    /* Check for bold support */
    if (g_bold || g_all_bold || g_no_bold) {
        has_bold = 1;
    }

    /* Get terminal size */
    if (get_term_size(&cols, &rows) == 0) {
        cols = 80;
        rows = 24;
    }

    /* Print message if specified */
    if (g_message_len > 0) {
        printf("\n");
        for (i = 0; i < g_message_len; i++) {
            printf("%c", g_message[i]);
        }
        printf("\n");
        message_printed = 1;
    }

    /* If no message and not in screensaver mode, print lock message */
    if (!message_printed && g_lock) {
        printf("\n");
        printf("CMatrix is running. Press Ctrl+C to exit.\n");
        printf("Press any key to close this window.\n");
    }

    /* Set up terminal settings */
    if (tcgetattr(STDIN_FILENO, &old_tios) == 0) {
        new_tios = old_tios;
        new_tios.c_lflag &= ~(ICANON | ECHO);
        new_tios.c_cc[VMIN] = 0;
        new_tios.c_cc[VTIME] = 0;
        tcsetattr(STDIN_FILENO, TCSANOW, &new_tios);
    }

    /* Set up signal handlers */
    signal(SIGWINCH, sigwinch_handler);
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    /* Main loop */
    while (1) {
        /* Check for input */
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);
        tv.tv_sec = g_delay;
        tv.tv_usec = 0;

        if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
            if (FD_ISSET(STDIN_FILENO, &readfds)) {
                ch = getchar();
                if (g_screensaver) {
                    exit(0);
                }
                if (g_lock) {
                    printf("\n");
                    printf("CMatrix is running. Press Ctrl+C to exit.\n");
                    printf("Press any key to close this window.\n");
                    break;
                }
            }
        }

        /* Print matrix effect */
        for (i = 0; i < rows; i++) {
            for (j = 0; j < cols; j++) {
                if (g_japanese) {
                    printf("%c", matrix_chars_japanese[j % 36]);
                } else {
                    printf("%c", matrix_chars[j % 2]);
                }
            }
            printf("\n");
        }
    }

    /* Restore terminal settings */
    if (tcsetattr(STDIN_FILENO, TCSANOW, &old_tios) == 0) {
        /* Success */
    }

    return exit_code;
}
CMATRIX_EOF"}

